        if (!SEA_ONLY_UZM) return uZm(latDeg, theta);
        double c = kappa < 0 ? 0 : (kappa > 1 ? 1 : kappa);
        return uZmSea(latDeg, theta) * (1.0 - c) + uZm(latDeg, theta) * c;
